fun cls(n):
    if (n < 0) then:
        return "neg"
    elif (n == 0) then:
        return "zero"
    elif (n < 10) then:
        return "small"
    else:
        return "big"
    end
end
print(cls(-1), cls(0), cls(5), cls(50))

fun even(n):
    if (n == 0) then:
        return true
    end
    return odd(n - 1)
end
fun odd(n):
    if (n == 0) then:
        return false
    end
    return even(n - 1)
end
print(even(10), odd(7), even(7))

